head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > ctrlShiftKey]<br/>Ctrl, Shift 키와 마우스 클릭을 복합적으로 사용하여 복수의 Cell 선택이 가능하게 설정합니다.",
    "validation" : [
        "useCtrlKey, useShiftKey 속성이 모두 true 인 경우에 정상적으로 동작합니다.",
        "true 설정 시 Ctrl 키를 누른 상태로 Cell 을 클릭하면 클릭된 Cell 이 추가로 선택됩니다.",
        "true 설정 시 Shift 키를 누른 상태로 Cell 을 클릭하면 Ctrl + 클릭 또는 클릭으로 선택된 마지막 Cell 부터 클릭된 Cell 까지 직사각형 범위의 Cell 이 추가로 선택됩니다.",
        "true 설정 시 Ctrl, Shift 키를 사용하여 Cell 을 클릭한 경우 기존 선택 상태는 유지됩니다.",
        "false(기본값) 설정 시 useCtrlKey, useShiftKey 속성값에 맞게 Cell 이 선택됩니다.",
        "focusMode='none' 이면 Cell 선택이 동작하지 않으므로 ctrlShiftKey 속성이 적용되지 않습니다.",
        "ctrlShiftKey=false, useCtrlKey=true, useShiftKey=true 일때 Ctrl+클릭은 기존 선택을 유지한 채 클릭된 Cell 이 선택되고, Shift+클릭은 처음 선택된 Cell 부터 클릭된 Cell 까지 직사각형 범위의 Cell 만 선택됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - con_focusMode      : cell(기본) / none  (정적 select1, @spec1 검증용. ctrlShiftKey 동작에는 focusMode!=none 필요)
//  - con_ctrlShiftKey   : 공통 gdl_boolean → getText() ('' 미설정=속성제외, 기본 false / 'true' / 'false')
//  - useCtrlKey, useShiftKey 는 true 로 하드코딩 (ctrlShiftKey 는 둘 다 true 일때만 정상 동작)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let vFocusMode    = con_focusMode.getValue();
    let vCtrlShiftKey = con_ctrlShiftKey.getText();

    // focusMode : 콤보 값 그대로 적용 (기본 cell)
    // useCtrlKey, useShiftKey : true 로 하드코딩 (ctrlShiftKey 는 둘 다 true 일때만 정상 동작)
    let properties = {
        focusMode : vFocusMode,
        useCtrlKey : true,
        useShiftKey : true
    };

    // ctrlShiftKey : 미설정('') 이면 속성 자체를 추가하지 않음(기본 false)
    if (vCtrlShiftKey === 'true') {
        properties.ctrlShiftKey = true;
    } else if (vCtrlShiftKey === 'false') {
        properties.ctrlShiftKey = false;
    }

    let cList = $c.gcm.createCList(properties);

    let lblDesc = 'GridView focusMode=' + vFocusMode
        + ', ctrlShiftKey=' + (vCtrlShiftKey === '' ? '(미설정)' : vCtrlShiftKey)
        + ', useCtrlKey=true, useShiftKey=true (하드코딩)'
        + ' / Cell 클릭 → Ctrl+클릭(추가) → Shift+클릭(범위 추가) 후 [선택 범위 확인] 버튼으로 확인';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + '"', '', 'label1');

    // 범위 선택 확인용 dataList 생성 (col1~col4, 6행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 6);
    scwin.fillData();

    // target 생성 (4컬럼 Body 그리드)
    await scwin.createGridView(cList);
}



// 범위 선택 확인용 데이터 (6행)
scwin.fillData = function () {
    let rows = [
        { col1: "A1", col2: "B1", col3: "C1", col4: "D1" },
        { col1: "A2", col2: "B2", col3: "C2", col4: "D2" },
        { col1: "A3", col2: "B3", col3: "C3", col4: "D3" },
        { col1: "A4", col2: "B4", col3: "C4", col4: "D4" },
        { col1: "A5", col2: "B5", col3: "C5", col4: "D5" },
        { col1: "A6", col2: "B6", col3: "C6", col4: "D6" },
    ];
    dlt_bind.setJSON(rows, false);
}



// gridView 동적 생성
scwin.createGridView = async function (cList) {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' checkAllType="false" id="" dataList="data:dlt_bind" style="width:520px;height:300px;">';
    s += '<w2:caption style="" id="caption1" value="ctrlShiftKey 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="120" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// 선택 범위 확인 :
//  - 사용자가 Cell 을 클릭한 뒤 Ctrl+클릭(추가) / Shift+클릭(직사각형 범위 추가) 하여 범위를 선택한 상태에서 호출.
//  - getAllFocusedIndex() 로 현재 선택(포커스)된 모든 Cell 의 {row, col} 목록과 개수를 출력.
//  - ctrlShiftKey=true : Ctrl 선택 유지 + Shift 직사각형 범위 추가 (기존 선택 유지) / false : useCtrlKey,useShiftKey 동작.
//  - focusMode='none' : Cell 선택 자체가 동작하지 않으므로 빈 목록.
scwin.btn_checkSelectedRange_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("[옵션] focusMode=" + target1.options.focusMode
        + " / ctrlShiftKey=" + target1.options.ctrlShiftKey
        + " / useCtrlKey=" + target1.options.useCtrlKey
        + " / useShiftKey=" + target1.options.useShiftKey);

    let focused = target1.getAllFocusedIndex();
    let cnt = focused ? focused.length : 0;
    bottom.setReturnValue("getAllFocusedIndex : " + JSON.stringify(focused));
    bottom.setReturnValue("선택된 Cell 개수 : " + cnt);
}
